import { expect, it } from "vitest";
import { UserSchema } from "../src/models/user.schema";

const base = { id: "1", name: "A", createdAt: new Date(), updatedAt: new Date() };

it("accepts valid email, rejects invalid", () => {
  expect(UserSchema.safeParse({ ...base, email: "a@b.co" }).success).toBe(true);
  expect(UserSchema.safeParse({ ...base, email: "nope" }).success).toBe(false);
});

